-- 0077_translate_content_hi.sql
-- Фаза 28: перевод контента программ — хинди (hi).
-- Переведено вручную с русского оригинала (с опорой на вычитанный
-- английский), с терминологией, принятой в залах этой страны. Английские
-- названия упражнений (Hip Thrust, Mountain Climbers…) оставлены как есть.
-- Применять после 0072. Сопоставление — по точному русскому тексту.
-- Безопасно выполнять повторно.

update public.workout_programs p
set title_hi = v.title, description_hi = v.description
from (values
  ('pohudenie-zhenshchiny-doma', 'वज़न घटाना · महिलाएँ · घर', 'महिलाओं के लिए वज़न घटाने का प्रोग्राम (घर पर) — DonatelleX, एक साल का प्रोग्राम। उपकरण: डम्बल, अलग-अलग टेंशन के रेज़िस्टेंस बैंड, मैट, मज़बूत प्लेटफ़ॉर्म/स्टेप (हो सके तो)'),
  ('pohudenie-zhenshchiny-zal', 'वज़न घटाना · महिलाएँ · जिम', 'महिलाओं के लिए वज़न घटाने का प्रोग्राम (जिम में) — एक साल का प्रोग्राम। उपकरण: ट्रेडमिल, एलिप्टिकल/स्की-अर्ग, मशीनें, डम्बल, केबल, मैट'),
  ('nabor-massy-zhenshchiny-doma', 'मसल गेन · महिलाएँ · घर', 'महिलाओं के लिए मसल गेन प्रोग्राम (घर पर) — एक साल का प्रोग्राम। उपकरण: डम्बल, अलग-अलग टेंशन के रेज़िस्टेंस बैंड, मैट, मज़बूत प्लेटफ़ॉर्म/स्टेप'),
  ('nabor-massy-zhenshchiny-zal', 'मसल गेन · महिलाएँ · जिम', 'महिलाओं के लिए मसल गेन प्रोग्राम (जिम में) — एक साल का प्रोग्राम «12 LEVELS»। उपकरण: बारबेल, डम्बल, मशीनें (Hip Thrust, Hack Squat, Leg Press, केबल), रेज़िस्टेंस बैंड, केटलबेल, TRX, मेडिसिन बॉल'),
  ('pohudenie-muzhchiny-doma', 'वज़न घटाना · पुरुष · घर', 'पुरुषों के लिए वज़न घटाने का प्रोग्राम (घर पर) — एक साल का प्रोग्राम। उपकरण: डम्बल, रेज़िस्टेंस बैंड, पुल-अप बार (हो सके तो), कुर्सी/बेंच, मैट'),
  ('pohudenie-muzhchiny-zal', 'वज़न घटाना · पुरुष · जिम', 'पुरुषों के लिए वज़न घटाने का प्रोग्राम (जिम में) — एक साल का प्रोग्राम। उपकरण: बारबेल, डम्बल, मशीनें, केबल, Battle Rope, SkiErg/रोइंग मशीन, कार्डियो ज़ोन (ट्रेडमिल/एलिप्टिकल/स्टेशनरी बाइक)'),
  ('nabor-massy-muzhchiny-doma', 'मसल गेन · पुरुष · घर', 'पुरुषों के लिए मसल गेन प्रोग्राम (घर पर) — एक साल का प्रोग्राम। उपकरण: डम्बल, रेज़िस्टेंस बैंड, पुल-अप बार (हो सके तो), कुर्सी/बेंच, मैट'),
  ('nabor-massy-muzhchiny-zal', 'मसल गेन · पुरुष · जिम', 'पुरुषों के लिए मसल गेन प्रोग्राम (जिम में) — एक साल का प्रोग्राम। उपकरण: पूरा जिम: बारबेल, डम्बल, मशीनें, पुल-अप बार, रोप, TRX, केटलबेल'),
  ('nabor-massy-nachinayushchim', 'शुरुआती लोगों के लिए मसल गेन', 'उन पुरुषों के लिए पहला प्रोग्राम जो जिम में मसल बनाना शुरू करना चाहते हैं। 7 दिन का साइकिल: अलग-अलग मसल ग्रुप के लिए 4 स्ट्रेंथ वर्कआउट और एब्स के साथ 3 दिन हल्का कार्डियो। शुरुआती लोगों के लिए सही — कोई मुश्किल तकनीक नहीं, फ़ोकस वॉल्यूम और सही फ़ॉर्म पर।')
) as v(slug, title, description)
where p.slug = v.slug;

